  if(/(привет|здравству|добрый день|доброе утро|добрый вечер|доброго времени|здравий|приветствую|хай\b)/.test(q))
    return{answer:`Здравствуйте${hi}! 👋 Я чат-бот центра «Гармония». Спросите про услуги, запись, сотрудников или мероприятия — подскажу и открою нужный раздел.`,actions:[]};
