    html+='<button class="pl-catcard" data-dept-idx="'+i+'" onclick="stOpenDept('+i+')" aria-label="'+dept.replace(/"/g,"&quot;")+', '+seen[dept]+' '+plWordForm(seen[dept],["сотрудник","сотрудника","сотрудников"])+'">'
        +'<span class="pl-catcard-ico">🏢</span>'
