function selectCity(cityKey,silent){
  if(!branchContent[cityKey])return;
  const wasSame=currentCity===cityKey;
  currentCity=cityKey;
  currentCityName=BRANCH_DISPLAY_NAMES[cityKey]||cityKey;
  localStorage.setItem("currentCity",currentCity);localStorage.setItem("currentCityName",currentCityName);
  servicesData=branchContent[currentCity].services;
  staffData=branchContent[currentCity].staff;
  const sel=document.getElementById("citySel");if(sel)sel.value=cityKey;
  const cd=document.getElementById("cityDisplay");if(cd)cd.textContent=cityPrefixed(currentCityName);
  updateHoursBanner();
  const profOpen=document.getElementById("profilePanel")&&document.getElementById("profilePanel").classList.contains("open");
  if(profOpen&&!wasSame){
    // Филиал сменили прямо в кабинете — не выкидываем на главную, обновляем сам кабинет.
    servicesData=branchContent[currentCity].services;staffData=branchContent[currentCity].staff;
    currentCatId=null;currentSvcList=null;
    showToast(`Филиал: ${cityPrefixed(currentCityName)}`);
    if(typeof showProfileSection==="function")showProfileSection("settings");
    return;
  }
  if(!silent&&!wasSame){
    navHistory=[];currentCatId=null;currentSvcList=null;
    document.getElementById("searchBar").classList.add("gone");
    addMsg(`📍 Переключено на: <b>${cityPrefixed(currentCityName)}</b>`,true);
    showMainMenu();
  }
}


// ═══════════════════════════════════════════════════════════════
// ЖИВОЙ ИНТЕРАКТИВНЫЙ МАСКОТ
// Робот слегка тянется за пальцем/курсором (3D-наклон) и реагирует
// на тап всплеском сердечек и короткой фразой. Чистый CSS/JS,
// без картинок-видео — работает поверх обычных <img> гифок.
// ═══════════════════════════════════════════════════════════════
(function(){
  var reduceMotion=window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  var PHRASES=["Привет! 👋","Чем помочь?","Я тут 💚","Задайте вопрос!","Рад видеть!","Слушаю вас"];
  var wired=new WeakSet();

  function wrapEl(mascotImg){
    // Поднимаемся до контейнера, который можно безопасно трансформировать
    return mascotImg.closest(".ga-bot-wrap,.asst-live,.onb-bot-live")||mascotImg.parentElement;
  }

  function attachTilt(container,mascotImg){
    if(reduceMotion)return;
    var raf=null,tx=0,ty=0;
    function apply(){
      mascotImg.style.transform="rotateX("+ty+"deg) rotateY("+tx+"deg)";
      raf=null;
    }
    function onMove(clientX,clientY){
      var r=container.getBoundingClientRect();
      if(!r.width||!r.height)return;
      var cx=r.left+r.width/2, cy=r.top+r.height/2;
      var dx=(clientX-cx)/(r.width/2), dy=(clientY-cy)/(r.height/2);
      dx=Math.max(-1,Math.min(1,dx)); dy=Math.max(-1,Math.min(1,dy));
      tx=dx*10; ty=-dy*10; // максимум ~10° наклона
      if(!raf)raf=requestAnimationFrame(apply);
    }
    function onLeave(){
      tx=0;ty=0;
      if(!raf)raf=requestAnimationFrame(apply);
    }
    container.style.perspective="400px";
    mascotImg.style.transition="transform .18s ease-out";
    mascotImg.style.willChange="transform";
    container.addEventListener("pointermove",function(e){onMove(e.clientX,e.clientY);});
    container.addEventListener("pointerleave",onLeave);
    // Плавный «взгляд» за пальцем и на мобильных, без блокировки скролла страницы
    container.addEventListener("touchmove",function(e){
      if(e.touches&&e.touches[0])onMove(e.touches[0].clientX,e.touches[0].clientY);
    },{passive:true});
    container.addEventListener("touchend",onLeave,{passive:true});
  }

  function burstHearts(container){
    var n=reduceMotion?0:4;
    for(var i=0;i<n;i++){
      var p=document.createElement("span");
      p.className="mascot-particle";
      p.textContent=(i%2===0)?"💚":"✨";
      var angle=(Math.random()*140-70)*Math.PI/180;
      var dist=34+Math.random()*22;
      p.style.setProperty("--mpx",(Math.sin(angle)*dist)+"px");
      p.style.setProperty("--mpy",(-Math.cos(angle)*dist-10)+"px");
      p.style.left="50%";p.style.top="38%";
      p.style.animationDelay=(i*45)+"ms";
      container.appendChild(p);
      setTimeout(function(el){el.remove();},900+i*45,p);
    }
  }

  function showBubble(container){
    if(container.querySelector(".mascot-bubble"))return;
    var b=document.createElement("div");
    b.className="mascot-bubble";
    b.textContent=PHRASES[Math.floor(Math.random()*PHRASES.length)];
    container.appendChild(b);
    requestAnimationFrame(function(){b.classList.add("show");});
    setTimeout(function(){b.classList.remove("show");setTimeout(function(){b.remove();},220);},1500);
  }

  function attachTap(container,mascotImg){
    container.style.cursor="pointer";
    container.addEventListener("pointerdown",function(e){
      mascotImg.classList.remove("mascot-poke");
      void mascotImg.offsetWidth; // рестарт CSS-анимации
      mascotImg.classList.add("mascot-poke");
      burstHearts(container);
      showBubble(container);
    });
  }

  function initOne(img){
    if(wired.has(img))return;
    wired.add(img);
    var container=wrapEl(img);
    if(!container)return;
    container.classList.add("mascot-interactive");
    attachTilt(container,img);
    attachTap(container,img);
  }

  function scan(root){
    (root||document).querySelectorAll(".ga-bot-img,.asst-live img,.onb-bot-live img").forEach(initOne);
  }

  var mo=new MutationObserver(function(muts){
    muts.forEach(function(m){
      m.addedNodes&&m.addedNodes.forEach(function(node){
        if(node.nodeType===1)scan(node);
      });
    });
  });
  document.addEventListener("DOMContentLoaded",function(){
    scan(document);
    if(document.body)mo.observe(document.body,{childList:true,subtree:true});
  });
  if(document.readyState!=="loading"){
    scan(document);
    if(document.body)mo.observe(document.body,{childList:true,subtree:true});
  }
})();

// ═══ Автоскрытие нижней капсулы меню при прокрутке ═══
// Вниз — уплывает за нижний край, чуть вверх / у краёв ленты — возвращается.
(function(){
  var nav=document.getElementById("tabBar");
  var sc=document.getElementById("chat");
  if(!nav||!sc)return;
  var last=sc.scrollTop,acc=0;
  sc.addEventListener("scroll",function(){
    var y=sc.scrollTop, d=y-last; last=y;
    var nearTop=y<24;
    var nearBottom=y+sc.clientHeight>=sc.scrollHeight-48;
    if(nearTop||nearBottom){ nav.classList.remove("nav-hidden"); acc=0; return; }
    acc+=d;
    if(acc>40){ nav.classList.add("nav-hidden"); acc=0; }       // уверенно вниз — прячем
    else if(acc<-16){ nav.classList.remove("nav-hidden"); acc=0; } // чуть вверх — показываем
    if(acc>64)acc=64;else if(acc<-64)acc=-64; // защита от дребезга
  },{passive:true});
})();

;

/* ───── js/header.js ───── */
/* ═══════════════════════════════════════════════════════════════════
   header.js — премиум-шапка «Гармония».
   Живой статус работы с обратным отсчётом, ближайшая запись, уведомления,
   быстрые действия (поиск, звонок, кабинет, смена филиала), аврора-фон,
   снег зимой, тема по времени суток, компактный режим при скролле.
   Только украшения и удобные ярлыки поверх существующих функций.
   ═══════════════════════════════════════════════════════════════════ */
(function(){
  "use strict";
  var reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion:reduce)").matches;
  var hdr = document.getElementById("appHdr");
  if(!hdr) return;

  function $(id){ return document.getElementById(id); }
  function getCityData(){
    try{ return (cityData && (cityData[currentCity]||cityData.gubkin)) || null; }catch(e){ return null; }
  }

  /* ─────────── Тема шапки по времени суток ─────────── */
  function applyTimeTheme(){
    var h=new Date().getHours(), cls="hdr-day";
    if(h>=5&&h<11) cls="hdr-morning";
    else if(h>=11&&h<17) cls="hdr-day";
    else if(h>=17&&h<22) cls="hdr-evening";
    else cls="hdr-night";
    hdr.classList.remove("hdr-morning","hdr-day","hdr-evening","hdr-night");
    hdr.classList.add(cls);
  }

  /* ─────────── Живой статус работы + обратный отсчёт ─────────── */
  function fmtDur(mins){
    mins=Math.max(0,Math.round(mins));
    var hh=Math.floor(mins/60), mm=mins%60;
    if(hh>0 && mm>0) return hh+" ч "+mm+" мин";
    if(hh>0) return hh+" ч";
    return mm+" мин";
  }
  function nextOpenInfo(cd, now){
    // ближайший рабочий день (Пн–Пт) и время открытия
    var probe=new Date(now.getTime());
    var openMins=cd.openH*60+cd.openM;
    for(var i=0;i<8;i++){
      var dow=probe.getDay();
      var isWeekday=dow>=1&&dow<=5;
      var sameDay=(i===0);
      var curMins=now.getHours()*60+now.getMinutes();
      if(isWeekday && (!sameDay || curMins<openMins)){
        var openAt=new Date(probe.getFullYear(),probe.getMonth(),probe.getDate(),cd.openH,cd.openM,0,0);
        var label = i===0 ? "сегодня" : (i===1 ? "завтра" : ["вс","пн","вт","ср","чт","пт","сб"][openAt.getDay()]);
        return { at:openAt, label:label };
      }
      probe.setDate(probe.getDate()+1);
    }
    return null;
  }
  function renderStatus(){
    var st=$("hdrStatus"); if(!st) return;
    var cd=getCityData(); if(!cd){ return; }
    var now=new Date();
    var dow=now.getDay(), mins=now.getHours()*60+now.getMinutes();
    var openMins=cd.openH*60+cd.openM, closeMins=cd.closeH*60+cd.closeM;
    var isWeekday=dow>=1&&dow<=5;
    var isOpen=isWeekday && mins>=openMins && mins<closeMins;
    var dot=st.querySelector(".hdr-status-dot"), txt=st.querySelector(".hdr-status-txt");
    var closeStr=cd.closeH+":"+String(cd.closeM).padStart(2,"0");
    st.classList.remove("is-open","is-soon","is-closed");
    if(isOpen){
      var toClose=closeMins-mins;
      st.classList.add(toClose<=60?"is-soon":"is-open");
      txt.innerHTML = toClose<=60
        ? "Открыто · закроется через "+fmtDur(toClose)
        : "Открыто · до "+closeStr;
    }else{
      st.classList.add("is-closed");
      var nx=nextOpenInfo(cd,now);
      if(nx){
        var diff=(nx.at-now)/60000;
        var openStr=cd.openH+":"+String(cd.openM).padStart(2,"0");
        // Коротко, чтобы строка помещалась в плашку рядом с кнопкой звонка
        txt.innerHTML = diff<=180
          ? "Закрыто · через "+fmtDur(diff)
          : "Закрыто · "+nx.label+" в "+openStr;
      }else{
        txt.textContent="Закрыто";
      }
    }
    // телефон филиала на кнопку звонка
    var call=$("hdrCall");
    if(call && cd.phoneRaw){ call.setAttribute("href","tel:+"+cd.phoneRaw); }
  }

  /* ─────────── Ближайшая запись ─────────── */
  function readHist(key){ try{ return JSON.parse(localStorage.getItem(key)||"[]"); }catch(e){ return []; } }
  function renderNext(){
    var chip=$("hdrNextChip"); if(!chip) return;
    var bh=readHist("bookingsHistory");
    var today=new Date(); today.setHours(0,0,0,0);
    var future=bh.filter(function(b){
      if(!b || !b.visitDate) return false;
      var d=new Date(b.visitDate+"T00:00:00");
      return !isNaN(d) && d>=today;
    }).sort(function(a,b){ return new Date(a.visitDate)-new Date(b.visitDate); });
    if(!future.length){ chip.classList.add("gone"); chip.innerHTML=""; return; }
    var nx=future[0];
    var d=new Date(nx.visitDate+"T00:00:00");
    var isToday=d.getTime()===today.getTime();
    var tmr=new Date(today.getTime()+86400000);
    var isTmr=d.getTime()===tmr.getTime();
    var months=["янв","фев","мар","апр","мая","июн","июл","авг","сен","окт","ноя","дек"];
    var whenLbl=isToday?"сегодня":(isTmr?"завтра":(d.getDate()+" "+months[d.getMonth()]));
    var title="Запись "+whenLbl+" в "+(nx.visitTime||"");
    var sub=(nx.spec||nx.dept||"Приём специалиста");
    chip.innerHTML=
      '<button class="hnc-main" type="button">'
      +'<span class="hnc-ico">📅</span>'
      +'<span class="hnc-txt"><b>'+esc(title)+'</b><span>'+esc(sub)+'</span></span>'
      +'<span class="hnc-arr">→</span>'
      +'</button>'
      +'<button class="hnc-cal" type="button" aria-label="Добавить в календарь" title="Добавить в календарь">'
      +'<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/></svg>'
      +'</button>';
    chip.classList.remove("gone");
    chip.querySelector(".hnc-main").onclick=function(){
      if(typeof openOrdersPanel==="function"){ openOrdersPanel(); if(typeof ordFilter==="function"){ var b=document.querySelector('.of-btn[data-f="bookings"]'); if(b)ordFilter("bookings",b); } }
    };
    chip.querySelector(".hnc-cal").onclick=function(ev){ ev.stopPropagation(); addToCalendar(nx); };
  }

  /* ─────────── .ics — добавить запись в календарь ─────────── */
  function addToCalendar(b){
    try{
      var date=(b.visitDate||"").replace(/-/g,"");
      var t=(b.visitTime||"09:00").replace(":","");
      if(date.length!==8){ if(typeof showToast==="function")showToast("Не удалось создать событие"); return; }
      var startH=parseInt(t.slice(0,2),10)||9, startM=parseInt(t.slice(2,4),10)||0;
      var endH=(startH+1)%24;
      var dtStart=date+"T"+String(startH).padStart(2,"0")+String(startM).padStart(2,"0")+"00";
      var dtEnd=date+"T"+String(endH).padStart(2,"0")+String(startM).padStart(2,"0")+"00";
      var summary="Запись — "+(b.spec||b.dept||"приём в «Гармонии»");
      var loc=(typeof currentCityName!=="undefined")?("«Гармония», "+currentCityName):"«Гармония»";
      var uid="garm-"+(b.num||Date.now())+"@garmoniya";
      var ics=["BEGIN:VCALENDAR","VERSION:2.0","PRODID:-//Garmoniya//CSON//RU","CALSCALE:GREGORIAN","BEGIN:VEVENT",
        "UID:"+uid,"DTSTART:"+dtStart,"DTEND:"+dtEnd,"SUMMARY:"+summary,"LOCATION:"+loc,
        "DESCRIPTION:Напоминание о записи в центр «Гармония»","BEGIN:VALARM","TRIGGER:-PT2H","ACTION:DISPLAY",
        "DESCRIPTION:Напоминание","END:VALARM","END:VEVENT","END:VCALENDAR"].join("\r\n");
      var blob=new Blob([ics],{type:"text/calendar;charset=utf-8"});
      var url=URL.createObjectURL(blob);
      var a=document.createElement("a"); a.href=url; a.download="zapis-garmoniya.ics";
      document.body.appendChild(a); a.click(); a.remove();
      setTimeout(function(){ URL.revokeObjectURL(url); },1500);
      if(typeof showToast==="function")showToast("Событие сохранено в календарь");
    }catch(e){ if(typeof showToast==="function")showToast("Не удалось создать событие"); }
  }

  /* ─────────── Аватар → кабинет ─────────── */
  function renderAvatar(){
    var av=$("hdrAvatar"); if(!av) return;
    var photo = (typeof getProfilePhoto==="function") ? getProfilePhoto() : "";
    var name = (typeof clientName!=="undefined" && clientName) ? clientName : "";
    if(photo){
      av.innerHTML='<img src="'+photo+'" alt="">';
    }else{
      var ini=(name||"?").split(" ").filter(Boolean).slice(0,2).map(function(w){return w[0];}).join("").toUpperCase()||"?";
      av.innerHTML='<span class="hdr-ava-init">'+ini+'</span>';
    }
  }

  /* ─────────── Уведомления (лента активности) ─────────── */
  function collectNotifs(){
    var items=[];
    readHist("ordersHistory").forEach(function(o){ items.push({t:o.createdAt||o.date, ico:"🛍️", title:"Заявка "+(o.num||""), sub:(o.status==="new"?"Отправлена":o.status||"")+(o.sum?" · "+o.sum+" ₽":"")}); });
    readHist("bookingsHistory").forEach(function(b){ items.push({t:b.createdAt||b.visitDate, ico:"📅", title:"Запись "+(b.num||""), sub:(b.visitDate||"")+" "+(b.visitTime||"")+" · "+(b.spec||b.dept||"")}); });
    readHist("taxiHistory").forEach(function(x){ items.push({t:x.createdAt||x.date, ico:"🚕", title:"Такси"+(x.date?" "+x.date:""), sub:(x.from||"")+" → "+(x.to||"")}); });
    items.sort(function(a,b){ return new Date(b.t||0)-new Date(a.t||0); });
    return items;
  }
  function notifSeen(){ return parseInt(localStorage.getItem("notifSeenTs")||"0",10); }
  function renderBell(){
    var badge=$("hdrBellBadge"); if(!badge) return;
    var seen=notifSeen();
    var unseen=collectNotifs().filter(function(n){ var ts=new Date(n.t||0).getTime(); return ts>seen; }).length;
    if(unseen>0){ badge.textContent=unseen>9?"9+":String(unseen); badge.classList.remove("gone"); }
    else{ badge.classList.add("gone"); }
  }
  function openNotifs(){
    var list=collectNotifs();
    var ovl=document.createElement("div"); ovl.className="hdr-sheet-ovl";
    ovl.onclick=function(e){ if(e.target===ovl) close(); };
    var rows = list.length ? list.slice(0,40).map(function(n){
      return '<div class="hnf-row"><span class="hnf-ico">'+n.ico+'</span><div class="hnf-txt"><b>'+esc(n.title)+'</b><span>'+esc(n.sub)+'</span></div></div>';
    }).join("") : '<div class="hnf-empty">🔔<div>Пока нет уведомлений</div><span>Здесь появятся статусы ваших заявок, записей и поездок</span></div>';
    ovl.innerHTML='<div class="hdr-sheet"><div class="hdr-sheet-grip"></div>'
      +'<div class="hdr-sheet-hd"><b>Уведомления</b><button class="hdr-sheet-x" aria-label="Закрыть">✕</button></div>'
      +'<div class="hnf-list">'+rows+'</div></div>';
    document.body.appendChild(ovl);
    requestAnimationFrame(function(){ ovl.classList.add("open"); });
    function close(){ ovl.classList.remove("open"); setTimeout(function(){ ovl.remove(); },300); }
    ovl.querySelector(".hdr-sheet-x").onclick=close;
    // всё увидено — гасим бейдж
    localStorage.setItem("notifSeenTs",String(Date.now()));
    renderBell();
  }
  function esc(s){ return String(s==null?"":s).replace(/[&<>"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c];}); }

  /* ─────────── Быстрая смена филиала ─────────── */
  function openCitySheet(){
    var cities=[["gubkin","Губкинский"],["purpe","мкр. Пурпе"],["muravlenko","Муравленко"],["noyabrsk","Ноябрьск"],["tarko","Тарко-Сале"],["urengoy","Уренгой"]];
    var ovl=document.createElement("div"); ovl.className="hdr-sheet-ovl";
    ovl.onclick=function(e){ if(e.target===ovl) close(); };
    var rows=cities.map(function(c){
      var active=(typeof currentCity!=="undefined"&&currentCity===c[0]);
      return '<button class="hcs-row'+(active?" active":"")+'" data-c="'+c[0]+'"><span class="hcs-pin">📍</span><span class="hcs-name">'+c[1]+'</span>'+(active?'<span class="hcs-check">✓</span>':"")+'</button>';
    }).join("");
    ovl.innerHTML='<div class="hdr-sheet"><div class="hdr-sheet-grip"></div>'
      +'<div class="hdr-sheet-hd"><b>Выбор филиала</b><button class="hdr-sheet-x" aria-label="Закрыть">✕</button></div>'
      +'<div class="hcs-list">'+rows+'</div></div>';
    document.body.appendChild(ovl);
    requestAnimationFrame(function(){ ovl.classList.add("open"); });
    function close(){ ovl.classList.remove("open"); setTimeout(function(){ ovl.remove(); },300); }
    ovl.querySelector(".hdr-sheet-x").onclick=close;
    ovl.querySelectorAll(".hcs-row").forEach(function(b){
      b.onclick=function(){ var k=b.dataset.c; close(); if(typeof selectCity==="function") selectCity(k); setTimeout(refreshAll,60); };
    });
  }

  /* ─────────── Поиск ─────────── */
  function openSearch(){
    // Поиск один — тот, что на странице услуг. Верхнюю строку не показываем,
    // чтобы два одинаковых поля не занимали место.
    var bar=$("searchBar"); if(bar) bar.classList.add("gone");
    if(typeof showServices==="function") showServices();
    var tries=0;
    (function focusPl(){
      var inp=$("plSearchInp");
      if(inp){ inp.focus(); inp.scrollIntoView({block:"nearest"}); return; }
      if(++tries<12) setTimeout(focusPl,80);
    })();
  }

  /* ─────────── Пасхалка: подмигивание логотипа ─────────── */
  function logoWink(){
    var logo=$("hdrLogo"); if(!logo||reduce) return;
    logo.classList.remove("wink"); void logo.offsetWidth; logo.classList.add("wink");
    var heart=document.createElement("span"); heart.className="hdr-logo-heart"; heart.textContent="💚";
    logo.appendChild(heart);
    setTimeout(function(){ heart.remove(); },900);
  }

  /* ─────────── Снег зимой ─────────── */
  function initSnow(){
    var box=$("hdrSnow"); if(!box||reduce) return;
    var m=new Date().getMonth(); // 0=янв … 11=дек
    var winter=(m>=10 || m<=2); // ноя–мар
    if(!winter) return;
    var n=10, html="";
    for(var i=0;i<n;i++){
      var left=(Math.random()*100).toFixed(1);
      var dur=(5+Math.random()*5).toFixed(1);
      var delay=(-Math.random()*8).toFixed(1);
      var size=(2+Math.random()*3).toFixed(1);
      var op=(0.35+Math.random()*0.4).toFixed(2);
      html+='<i style="left:'+left+'%;width:'+size+'px;height:'+size+'px;opacity:'+op+';animation-duration:'+dur+'s;animation-delay:'+delay+'s"></i>';
    }
    box.innerHTML=html;
  }

  /* --- Компактный режим отключён намеренно: изменение высоты шапки при
     скролле меняло высоту области прокрутки и «отбивало» палец на iOS
     (лента переставала листаться). Шапка остаётся стабильной высоты. --- */

  /* ─────────── Общий рефреш ─────────── */
  function refreshAll(){ try{ applyTimeTheme(); renderStatus(); renderNext(); renderAvatar(); renderBell(); }catch(e){} }
  window.hdrRefresh = refreshAll;              // чтобы другие модули могли обновить шапку
  window.hdrUpdateStatus = function(){ try{ renderStatus(); }catch(e){} };

  /* ─────────── Привязка событий ─────────── */
  function bind(id,fn){ var el=$(id); if(el) el.addEventListener("click",fn); }
  bind("hdrSearchBtn",openSearch);
  bind("hdrBellBtn",openNotifs);
  bind("hdrAvatar",function(){ if(typeof closeAllPanels==="function")closeAllPanels(); if(typeof openProfilePanel==="function")openProfilePanel(); });
  bind("hdrCityBtn",openCitySheet);
  bind("hdrLogo",logoWink);

  /* старт */
  initSnow(); refreshAll();
  document.addEventListener("DOMContentLoaded",refreshAll);
  setTimeout(refreshAll,400);        // после инициализации приложения (имя, фото, история)
  setInterval(renderStatus,30000);   // отсчёт «живой»
  setInterval(refreshAll,120000);    // тема/записи/уведомления раз в 2 мин
  window.addEventListener("focus",refreshAll);
})();

;

/* ───── js/polish.js ───── */
/* ═══════════════════════════════════════════════════════════════════
   polish.js — визуальный слой поверх приложения «Гармония».
   Только украшения: не меняет данные, логику и разметку экранов.
   Всё в try/catch и уважает prefers-reduced-motion.
   ═══════════════════════════════════════════════════════════════════ */
(function(){
  "use strict";
  var reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion:reduce)").matches;
  var chat = document.getElementById("chat");
  var shell = document.getElementById("shell");

  /* ─────────── 1. Появление карточек при заходе на экран ───────────
     Только статические списки-меню. Ленту новостей НЕ трогаем —
     она должна листаться как обычная соцлента, без анимаций на каждой карточке. */
  var REVEAL_SEL = ".sp-item,.sp-g,.pl-catcard,.ev-card,.staff-card-inline,.pcard,.ord-card";
  var io = null;
  if(!reduce && "IntersectionObserver" in window){
    io = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if(e.isIntersecting){ show(e.target); io.unobserve(e.target); }
      });
    },{ root: chat || null, rootMargin:"0px 0px -4% 0px", threshold:0.04 });
  }
  function show(el){
    el.classList.add("rv-in");
    // после появления снимаем все GPU-подсказки, чтобы не оставлять promoted-слои
    var done=function(){ el.classList.remove("rv-init","rv-in"); el.style.removeProperty("--rv-d"); };
    el.addEventListener("transitionend",done,{once:true});
    setTimeout(done,700);
  }
  function armReveals(){
    if(!io || !chat) return;
    try{
      var nodes=chat.querySelectorAll(REVEAL_SEL), batch=[];
      for(var i=0;i<nodes.length;i++){
        var n=nodes[i];
        if(n.dataset.rv) continue;
        if(n.closest(".pl-skel-card,.msg,.news-carousel-track")) continue;
        n.dataset.rv="1"; n.classList.add("rv-init"); batch.push(n);
      }
      batch.forEach(function(n,i){
        n.style.setProperty("--rv-d",(Math.min(i,8)*45)+"ms");
        io.observe(n);
        setTimeout(function(){ if(!n.classList.contains("rv-in")) show(n); },1400); // страховка
      });
    }catch(e){}
  }

  /* ─────────── 2. Кросс-фейд ТОЛЬКО при реальной смене раздела ─────────── */
  function triggerViewSwap(){
    if(reduce || !chat) return;
    if(shell && shell.classList.contains("assistant-mode")) return; // в чате бота не мигаем
    chat.classList.remove("view-swap"); void chat.offsetWidth; chat.classList.add("view-swap");
  }

  /* Наблюдаем ТОЛЬКО прямых детей #chat (subtree:false).
     Обновление лайка/каруселей — это глубокие изменения, они сюда не долетают,
     поэтому лента больше не мигает от лайка и листается чисто. */
  if(chat && "MutationObserver" in window){
    var pending=false;
    var mo=new MutationObserver(function(records){
      var added=false, removed=false;
      for(var i=0;i<records.length;i++){
        if(records[i].addedNodes.length) added=true;
        if(records[i].removedNodes.length) removed=true;
      }
      if(added && removed) triggerViewSwap();
      if(added && !pending){
        pending=true;
        requestAnimationFrame(function(){ pending=false; armReveals(); tagImages(); });
      }
    });
    mo.observe(chat,{childList:true, subtree:false});
  }

  /* ─────────── 3. Всплеск сердечек на лайке ─────────── */
  function heartBurst(btn){
    if(reduce) return;
    try{
      var r=btn.getBoundingClientRect();
      var layer=document.createElement("div"); layer.className="like-burst";
      layer.style.left=(r.left+r.width/2)+"px"; layer.style.top=(r.top+r.height/2)+"px";
      for(var i=0;i<6;i++){
        var h=document.createElement("i");
        var ang=(-90 + (i-2.5)*22) * Math.PI/180;
        var dist=24+Math.random()*20;
        h.style.setProperty("--hx",(Math.cos(ang)*dist).toFixed(1)+"px");
        h.style.setProperty("--hy",(Math.sin(ang)*dist-12).toFixed(1)+"px");
        h.style.setProperty("--hd",(Math.random()*60).toFixed(0)+"ms");
        h.style.setProperty("--hs",(0.7+Math.random()*0.5).toFixed(2));
        layer.appendChild(h);
      }
      document.body.appendChild(layer);
      setTimeout(function(){ layer.remove(); },850);
    }catch(e){}
  }
  if(typeof window.toggleNewsLike==="function"){
    var _like=window.toggleNewsLike;
    window.toggleNewsLike=function(id,btn){
      var wasLiked = btn && btn.classList.contains("liked");
      var res=_like.apply(this,arguments);
      if(btn && !wasLiked) heartBurst(btn);
      return res;
    };
  }

  /* ─────────── 4. Проявление картинок — ОТКЛЮЧЕНО ───────────
     Из-за гонки события load картинки иногда оставались невидимыми
     (лента выглядела «не работающей»). Возвращено к оригиналу. */
  function tagImages(){ /* no-op */ }

  /* ─────────── 5. Брендовый сплэш при запуске ─────────── */
  (function splash(){
    var s=document.getElementById("appSplash");
    if(!s) return;
    function hide(){
      if(s.classList.contains("hide")) return;
      s.classList.add("hide");
      setTimeout(function(){ if(s.parentNode) s.remove(); },560);
    }
    var t0=performance.now();
    function ready(){ setTimeout(hide,Math.max(0,700-(performance.now()-t0))); }
    if(document.readyState==="complete") ready();
    else window.addEventListener("load",ready,{once:true});
    setTimeout(hide,3500);
  })();

  if(!reduce){ requestAnimationFrame(function(){ armReveals(); tagImages(); }); }
})();

;

/* ───── js/extra.js ───── */
/* ═══════════════════════════════════════════════════════════════════
   extra.js — самодостаточный слой удобств поверх приложения «Гармония».
   Ничего не меняет в логике записи/заявок/услуг — только добавляет.
   Всё в try/catch, уважает prefers-reduced-motion.
   ═══════════════════════════════════════════════════════════════════ */
(function(){
  "use strict";
  var reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion:reduce)").matches;
  var chat = document.getElementById("chat");
  function toast(m){ if(typeof showToast==="function") showToast(m); }

  /* ─────────── 1. PWA: установка на экран + офлайн ─────────── */
  if("serviceWorker" in navigator){
    window.addEventListener("load",function(){
      navigator.serviceWorker.register("./sw.js").catch(function(){});
    });
  }

  /* ─────────── 2. Кнопка «Наверх» ─────────── */
  (function(){
    if(!chat) return;
    var btn=document.createElement("button");
    btn.id="backTop"; btn.type="button"; btn.setAttribute("aria-label","Наверх");
    btn.innerHTML='<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M12 19V5M5 12l7-7 7 7"/></svg>';
    document.body.appendChild(btn);
    var ticking=false;
    chat.addEventListener("scroll",function(){
      if(ticking) return; ticking=true;
      requestAnimationFrame(function(){ btn.classList.toggle("show", chat.scrollTop>620); ticking=false; });
    },{passive:true});
    btn.onclick=function(){ chat.scrollTo({top:0,behavior:reduce?"auto":"smooth"}); };
  })();

  /* ─────────── 3. Тонкая полоса загрузки при переходах ─────────── */
  var progEl=null, progT=0;
  function progStart(){
    if(reduce) return;
    if(!progEl){ progEl=document.createElement("div"); progEl.id="navProgress"; document.body.appendChild(progEl); }
    progEl.classList.remove("done"); progEl.classList.remove("go"); void progEl.offsetWidth; progEl.classList.add("go");
    clearTimeout(progT); progT=setTimeout(progDone,520);
  }
  function progDone(){ if(progEl){ progEl.classList.add("done"); } }
  ["tabGo","goBack","showMainMenu","openCart","openOrdersPanel","openProfilePanel"].forEach(function(n){
    if(typeof window[n]==="function"){ var o=window[n]; window[n]=function(){ progStart(); return o.apply(this,arguments); }; }
  });

  /* 4. Тёмная тема и автотема по времени суток удалены. */

  /* ─────────── 5. Копирование телефона/адреса по тапу ─────────── */
  document.addEventListener("click",function(e){
    var el=e.target && e.target.closest && e.target.closest('a[href^="tel:"],[data-copy]');
    if(!el) return;
    var val=el.getAttribute("data-copy") || (el.getAttribute("href")||"").replace("tel:","").trim();
    if(!val) return;
    if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(val).then(function(){ toast("📋 Скопировано: "+val); }).catch(function(){});
    }
  },true);

  /* ─────────── 6. Хаптик-отклик на ключевых действиях ─────────── */
  if(navigator.vibrate){
    document.addEventListener("click",function(e){
      var t=e.target && e.target.closest && e.target.closest(".tb,.hdr-ico-btn,.hdr-avatar,.nva-like,.hnc-cal,[data-haptic]");
      if(t){ try{ navigator.vibrate(7); }catch(e2){} }
    },true);
  }

  /* ─────────── 7. Индикатор офлайна ─────────── */
  (function(){
    var bar=document.createElement("div");
    bar.id="offlineBar"; bar.textContent="Нет сети — показываем сохранённое";
    document.body.appendChild(bar);
    function upd(){ bar.classList.toggle("show", !navigator.onLine); }
    window.addEventListener("online",function(){ upd(); toast("🌐 Соединение восстановлено"); });
    window.addEventListener("offline",upd);
    upd();
  })();

  /* ─────────── 8. Ленивая загрузка картинок контента ─────────── */
  function lazify(){
    if(!chat) return;
    try{
      var imgs=chat.querySelectorAll("img:not([data-lz])");
      for(var i=0;i<imgs.length;i++){
        var im=imgs[i];
        if(im.closest(".ga-bot-wrap,.asst-live,.onb-bot-live")||im.classList.contains("ga-bot-img")){ im.setAttribute("data-lz","1"); continue; }
        im.setAttribute("data-lz","1");
        if(!im.hasAttribute("loading")) im.setAttribute("loading","lazy");
        if(!im.hasAttribute("decoding")) im.setAttribute("decoding","async");
      }
    }catch(e){}
  }
  if(chat && "MutationObserver" in window){
    var lzPend=false;
    new MutationObserver(function(){
      if(lzPend) return; lzPend=true;
      requestAnimationFrame(function(){ lzPend=false; lazify(); });
    }).observe(chat,{childList:true,subtree:false});
  }
  lazify();

  /* ─────────── 9. Праздничный акцент в шапке ─────────── */
  (function holiday(){
    var hdr=document.getElementById("appHdr"); if(!hdr) return;
    var now=new Date(), mo=now.getMonth()+1, day=now.getDate(), emo="", cls="";
    if((mo===12&&day>=20)||(mo===1&&day<=10)){ emo="❄️"; cls="hl-ny"; }
    else if(mo===2&&day>=20&&day<=24){ emo="⭐"; cls="hl-def"; }
    else if(mo===3&&day>=6&&day<=8){ emo="🌷"; cls="hl-wom"; }
    else if(mo===5&&day>=1&&day<=9){ emo="🎗️"; cls="hl-vict"; }
    else if(mo===6&&day===8){ emo="💚"; cls="hl-soc"; } // День соцработника
    if(!emo) return;
    hdr.classList.add("hdr-holiday",cls);
    var b=document.createElement("span"); b.className="hdr-holiday-emo"; b.textContent=emo; b.setAttribute("aria-hidden","true");
    hdr.appendChild(b);
  })();

})();

;

/* ───── js/tabdrag.js ───── */
/* ══════════════════════════════════════════════════════════════
   ГАРМОНИЯ — перетаскиваемый ползунок нижнего меню.

   Тянешь «пилюлю» пальцем вдоль таб-бара — она следует за пальцем,
   подсвечивая вкладку под ней; на отпускании пружиной доводится
   до ближайшей вкладки и открывает её. Обычный тап работает как
   раньше (порог THRESHOLD отделяет тап от перетаскивания).

   Чистое добавление: existing-код не меняется, всё через globals.
   ══════════════════════════════════════════════════════════════ */
(function(){
  "use strict";
  if(window.__garmTabDrag) return; window.__garmTabDrag=true;

  var THRESHOLD = 6; // px — дальше этого жест считается перетаскиванием

  function init(){
    var bar = document.getElementById("tabBar");
    var pill = document.getElementById("tbPill");
    if(!bar || !pill) return;

    var down=false, moved=false, justDragged=false;
    var slots=[], pillW=0, minX=0, maxX=0, barLeft=0, barClientLeft=0;
    var downX=0, lastX=0, pointerId=null;

    // Ближайшая вкладка к экранной координате X.
    function nearest(clientX){
      var best=slots[0], bd=Infinity;
      for(var i=0;i<slots.length;i++){
        var d=Math.abs(slots[i].cx-clientX);
        if(d<bd){bd=d;best=slots[i];}
      }
      return best;
    }

    // Замер геометрии в момент касания (layout статичен во время жеста).
    function measure(){
      var br=bar.getBoundingClientRect();
      barLeft=br.left; barClientLeft=bar.clientLeft;
      slots=[];
      bar.querySelectorAll(".tb").forEach(function(btn){
        var r=btn.getBoundingClientRect();
        slots.push({
          btn:btn,
          x:r.left-br.left-barClientLeft+3,   // та же формула, что в movePillTo
          w:r.width-6,
          cx:r.left+r.width/2
        });
      });
      if(!slots.length) return false;
      pillW=slots[0].w;
      minX=slots[0].x;
      maxX=slots[slots.length-1].x;
      return true;
    }

    // Ставит пилюлю по центру под палец, с ограничением по краям.
    function setPill(clientX){
      var x=clientX-barLeft-barClientLeft-pillW/2;
      if(x<minX)x=minX;
      if(x>maxX)x=maxX;
      pill.style.transition="none";
      pill.style.width=pillW+"px";
      pill.style.transform="translate3d("+x+"px,0,0) scale(1.05)";
    }

    // Живая подсветка вкладки под пальцем.
    function highlight(clientX){
      var n=nearest(clientX);
      bar.querySelectorAll(".tb").forEach(function(b){b.classList.remove("active");});
      n.btn.classList.add("active");
    }

    // Открыть конкретную вкладку без опоры на event (аналог tabGo).
    function activate(btn){
      var oc=btn.getAttribute("onclick")||"";
      var m=/tabGo\(['"](\w+)['"]\)/.exec(oc);
      var t=m?m[1]:null;
      bar.classList.remove("nav-hidden");
      bar.querySelectorAll(".tb").forEach(function(b){b.classList.remove("active");});
      btn.classList.add("active");
      if(typeof window.movePillTo==="function") window.movePillTo(btn);
      var run=function(){
        if(t==="home"&&window.showMainMenu)showMainMenu();
        else if(t==="menu"&&window.showMenuPage)showMenuPage();
        else if(t==="cart"&&window.openCart)openCart();
        else if(t==="orders"&&window.openOrdersPanel)openOrdersPanel();
        else if(t==="profile"&&window.openProfilePanel)openProfilePanel();
      };
      if((t==="home"||t==="menu")&&window.garmVT) window.garmVT(run);
      else run();
    }

    bar.addEventListener("pointerdown",function(e){
      if(e.button && e.button!==0) return;   // только основная кнопка/палец
      if(!measure()) return;
      down=true; moved=false;
      downX=e.clientX; lastX=e.clientX; pointerId=e.pointerId;
      // Захват указателя НЕ ставим здесь: с мышью он перенаправляет click
      // на сам таб-бар, и onclick кнопки-вкладки не срабатывает.
    });

    bar.addEventListener("pointermove",function(e){
      if(!down) return;
      lastX=e.clientX;
      if(!moved){
        if(Math.abs(e.clientX-downX) < THRESHOLD) return; // ещё тап, не тянем
        moved=true;
        pill.classList.add("tb-pill-drag");
        try{ bar.setPointerCapture(e.pointerId); }catch(_){}  // захват — только для перетаскивания
      }
      setPill(e.clientX);
      highlight(e.clientX);
      e.preventDefault();
    });

    function end(){
      if(!down) return;
      down=false;
      try{ if(pointerId!=null) bar.releasePointerCapture(pointerId); }catch(_){}
      pointerId=null;
      if(moved){
        moved=false;
        pill.classList.remove("tb-pill-drag");
        pill.style.transition="";   // вернуть CSS-пружину; transform/width
                                    // перезапишет movePillTo внутри activate()
        justDragged=true;           // проглотить следующий синтетический click
        setTimeout(function(){ justDragged=false; },400);
        activate(nearest(lastX).btn);
      }
      // moved=false — это был тап: пилюлю не трогаем, сработает штатный onclick
    }
    bar.addEventListener("pointerup",end);
    bar.addEventListener("pointercancel",end);

    // После настоящего перетаскивания гасим ровно один click,
    // чтобы вкладка не открылась дважды.
    bar.addEventListener("click",function(e){
      if(justDragged){ e.stopPropagation(); e.preventDefault(); justDragged=false; }
    },true);
  }

  if(document.readyState==="loading") document.addEventListener("DOMContentLoaded",init);
  else init();
})();

;

/* ───── js/navfix.js ───── */
/* ══════════════════════════════════════════════════════════════
   ГАРМОНИЯ — починка навигации «Назад».

   Проблема: разделы открываются разными путями (плитки Главной,
   быстрые действия, поиск, прямые onclick="showTaxi()"), и только
   часть из них клала экран в navHistory. В остальных случаях
   кнопка «← Назад в меню» ничего не делала.

   Решение: оборачиваем функции разделов так, что при входе они
   САМИ запоминают экран, с которого их открыли. Существующие
   вызовы pushNav продолжают работать — дубли не создаются.

   Чистое добавление: ни одна строка старого кода не меняется.
   ══════════════════════════════════════════════════════════════ */
(function(){
  "use strict";
  if(window.__garmNavFix) return; window.__garmNavFix=true;

  // Разделы, внутри которых есть кнопка «Назад».
  var SECTIONS=["showServices","showBooking","showTaxi","showStaff","showCallback",
                "showEvents","showNews","showContacts","showFeedback","showGallery",
                "showMoroshkaInfo"];

  function activeTab(){
    var b=document.querySelector(".tb.active");
    if(!b) return "home";
    var m=/tabGo\(['"](\w+)['"]\)/.exec(b.getAttribute("onclick")||"");
    return m?m[1]:"home";
  }

  // Экран, на который логично вернуться из раздела.
  function originScreen(){
    return activeTab()==="menu" && typeof window.showMenuPage==="function"
      ? window.showMenuPage
      : window.showMainMenu;
  }

  function init(){
    if(typeof window.pushNav!=="function") return;

    SECTIONS.forEach(function(name){
      var orig=window[name];
      if(typeof orig!=="function" || orig.__garmWrapped) return;

      var wrapped=function(){
        try{
          var hist=window.navHistory;
          var origin=originScreen();
          // Кладём экран возврата, только если стек пуст — тогда
          // мы пришли напрямую. Если pushNav уже отработал (переход
          // из «Услуг» или вглубь), ничего не трогаем.
          if(Array.isArray(hist) && hist.length===0 && typeof origin==="function"){
            window.pushNav(origin);
          }
        }catch(e){}
        return orig.apply(this, arguments);
      };
      wrapped.__garmWrapped=true;
      window[name]=wrapped;
    });
  }

  // Оборачиваем после того, как все скрипты объявили свои функции.
  if(document.readyState==="loading") document.addEventListener("DOMContentLoaded",init);
  else init();
})();

;

/* ───── js/chatflow.js ───── */
/* ═══════════════════════════════════════════════════════════════════
   chatflow.js — «умная» часть чат-бота «Гармония».

   Что умеет:
   1) Знает весь прейскурант филиала до мелочей: название, цена,
      цена по карте «Морошка», длительность, раздел. Отвечает на
      «сколько стоит…», «что входит в раздел…», «есть ли у вас…».
   2) Оформляет заявку на услуги прямо в переписке: находит услугу,
      кладёт в корзину, собирает ФИО и телефон и отправляет заявку
      тем же путём, что и экран корзины.
   3) Заказывает социальное такси диалогом: откуда, куда, дата,
      время, пассажиры, тариф — и предупреждает, что заказ
      принимается не позднее чем за сутки.

   Файл ничего не удаляет и не переписывает: он только расширяет
   askFlow() и пользуется существующими функциями приложения.
   ═══════════════════════════════════════════════════════════════════ */
(function(){
  "use strict";

  /* ─────────── Состояние диалога ─────────── */
  var CF = { mode:null, step:null, data:{} };
  function reset(){ CF = { mode:null, step:null, data:{} }; }
  window.cfReset = reset;

  /* ─────────── Кнопки: реестр, чтобы не городить строки в onclick ─────────── */
  var BTNS = [];
  window.cfBtn = function(i){
    var b = BTNS[i];
    if (!b) return;
    if (b.echo) addMsg(b.echo, false);
    var out = b.run();
    if (out) say(out);
  };
  function btn(label, run, opts){
    opts = opts || {};
    BTNS.push({ run:run, echo:opts.echo });
    return '<button type="button" class="act-btn ' + (opts.cl||"teal") + '" ' +
           'onclick="cfBtn(' + (BTNS.length-1) + ')">' + label + '</button>';
  }
  function row(buttons){
    return buttons.length ? '<div class="asst-actions">' + buttons.join("") + '</div>' : "";
  }
  function say(html){
    if (typeof showTyping === "function") showTyping(function(){ addMsg(html, true); });
    else addMsg(html, true);
  }
  function esc(s){ return String(s==null?"":s).replace(/</g,"&lt;").replace(/>/g,"&gt;"); }
  function norm(s){ return (typeof asstNorm === "function") ? asstNorm(s) : String(s||"").toLowerCase(); }
  function money(n){ return Number(n).toLocaleString("ru-RU") + " ₽"; }

  /* ═══════════ 1. База знаний по услугам ═══════════ */

  /* Плоский индекс: одна запись — одна услуга из прейскуранта филиала. */
  function index(){
    if (typeof servicesData === "undefined" || !servicesData || !servicesData.length) return [];
    var out = [];
    servicesData.forEach(function(cat){
      (cat.items||[]).forEach(function(it, idx){
        var dur = String(it.n||"").match(/(\d+)\s*мин/);
        out.push({
          uid: cat.id*1000 + idx, catId: cat.id, catName: cat.name, icon: cat.icon || "",
          idx: idx, name: it.n, price: it.p, mor: (it.m==null ? null : it.m),
          minutes: dur ? parseInt(dur[1]) : null, key: norm(it.n + " " + cat.name)
        });
      });
    });
    return out;
  }

  /* Поиск услуги по словам запроса.
     Русские окончания гасим сравнением по основе слова (первые 5 букв),
     поэтому «уборку квартиры» находит «Уборка квартиры». */
  var STOP = ["услуга","услуги","услугу","сколько","стоит","цена","стоимость","хочу","нужен","нужна","нужно",
              "закажи","заказать","заказ","оформить","заявка","заявку","запиши","записаться","можно","есть",
              "вас","мне","для","как","что","это","пожалуйста","подскажите","хотел","хотела","бы"];
  function queryWords(q){
    return norm(q).split(" ").filter(function(w){ return w.length > 2 && STOP.indexOf(w) < 0; });
  }

  /* Совпадение по общей основе: «уборку» и «уборка» имеют общее начало «уборк». */
  function commonPrefix(a, b){
    var n = Math.min(a.length, b.length), i = 0;
    while (i < n && a[i] === b[i]) i++;
    return i;
  }
  function matches(word, tokens){
    var best = 0;
    for (var i = 0; i < tokens.length; i++) {
      var t = tokens[i];
      if (t === word) return word.length + 3;                 /* точное слово */
      if (t.length < 4 || word.length < 4) continue;          /* короткие слова не сравниваем */
      var cp = commonPrefix(word, t);
      if (cp >= 4 && cp >= Math.min(word.length, t.length) - 3) best = Math.max(best, cp);
    }
    return best;
  }
  function findServices(q, limit){
    var words = queryWords(q);
    if (!words.length) return [];
    var res = [];
    index().forEach(function(s){
      var tokens = s.key.split(/[^а-яёa-z0-9]+/i).filter(Boolean);
      var score = 0, hits = 0;
      words.forEach(function(w){
        var m = matches(w, tokens);
        if (m) { score += m; hits++; }
      });
      if (hits) res.push({ s:s, score:score, hits:hits });
    });
    /* сначала те, где совпало больше слов запроса */
    res.sort(function(a,b){ return (b.hits - a.hits) || (b.score - a.score); });
    var topHits = res.length ? res[0].hits : 0;
    res = res.filter(function(r){ return r.hits === topHits && r.score >= 4; });
    var out = res.slice(0, limit || 6).map(function(r){ return r.s; });
    /* full = нашлись все значимые слова запроса, а не одно из нескольких */
    out.full = topHits >= words.length;
    return out;
  }

  /* Карточка услуги со всеми подробностями. */
  function serviceCard(s){
    var rows = [
      ["Раздел", esc(s.catName)],
      ["Цена", money(s.price)]
    ];
    if (s.mor != null && s.mor !== s.price) rows.push(["По карте «Морошка»", money(s.mor)]);
    if (s.minutes) rows.push(["Длительность", s.minutes + " мин"]);
    return '<div class="cf-card">' +
      '<div class="cf-card-ttl">' + esc(s.name) + '</div>' +
      rows.map(function(r){
        return '<div class="cf-row"><span>' + r[0] + '</span><b>' + r[1] + '</b></div>';
      }).join("") +
    '</div>';
  }

  function priceLine(s){
    return "• " + esc(s.name) + " — <b>" + money(s.price) + "</b>" +
           (s.mor != null && s.mor !== s.price ? ' <span class="cf-mor">по «Морошке» ' + money(s.mor) + "</span>" : "");
  }

  /* Ответ про конкретную услугу + кнопки действий. */
  function answerService(s){
    return "Вот что у меня по этой услуге:" + serviceCard(s) +
      row([
        btn("Добавить в заявку", function(){ return addService(s); }, { echo:"Добавить в заявку: " + s.name }),
        btn("Открыть в прейскуранте", function(){ showCategory(s.catId, s.uid); return ""; }, { cl:"outline" })
      ]);
  }

  /* Несколько подходящих услуг — даём выбрать. */
  function answerChoice(list, head){
    var buttons = list.slice(0,5).map(function(s){
      return btn(esc(s.name) + " · " + money(s.price), function(){ return answerService(s); },
                 { cl:"outline", echo:s.name });
    });
    return (head || "Нашёл несколько подходящих услуг — какая нужна?") + row(buttons);
  }

  /* Весь раздел целиком. */
  function answerCategory(cat){
    var lines = (cat.items||[]).slice(0,14).map(function(it, i){
      return priceLine({ name:it.n, price:it.p, mor:(it.m==null?null:it.m) });
    }).join("<br>");
    var more = (cat.items||[]).length > 14 ? "<br>…и ещё " + ((cat.items||[]).length - 14) + " услуг в разделе." : "";
    return "<b>" + esc(cat.name) + "</b> — " + (cat.items||[]).length + " услуг:<br><br>" + lines + more +
      row([ btn("Открыть раздел", function(){ showCategory(cat.id); return ""; }) ]);
  }

  function findCategory(q){
    var nq = norm(q);
    if (typeof servicesData === "undefined") return null;
    var best = null, bs = 0;
    servicesData.forEach(function(c){
      var words = norm(c.name).split(" ").filter(function(w){ return w.length > 3; });
      var sc = 0;
      words.forEach(function(w){ if (nq.indexOf(w) >= 0) sc += w.length; });
      if (sc > bs) { bs = sc; best = c; }
    });
    return bs >= 5 ? best : null;
  }

  /* ═══════════ 2. Заявка на услуги прямо из чата ═══════════ */

  function addService(s){
    addToCart(s.uid, s.name, (hasMoroshka && s.mor != null) ? s.mor : s.price, null, s.price, s.mor);
    var total = cart.reduce(function(a,i){ return a + i.price*i.qty; }, 0);
    return "Добавил в заявку: <b>" + esc(s.name) + "</b>.<br>Сейчас в заявке " + cart.length +
      (cart.length === 1 ? " услуга" : " услуг") + " на " + money(total) + "." +
      row([
        btn("Оформить заявку", function(){ return startOrder(); }, { echo:"Оформить заявку" }),
        btn("Добавить ещё услугу", function(){ CF.mode="order"; CF.step="pick";
              return "Какую услугу добавить? Напишите название или направление — например «уборка» или «массаж»."; },
            { cl:"outline", echo:"Добавить ещё услугу" }),
        btn("Показать заявку", function(){ openCart(); return ""; }, { cl:"outline" })
      ]);
  }

  /* Оформление: проверяем ФИО и телефон, показываем состав, отправляем. */
  function startOrder(){
    if (!cart.length) {
      CF.mode = "order"; CF.step = "pick";
      return "В заявке пока пусто. Напишите, какая услуга нужна — найду её в прейскуранте и добавлю.";
    }
    if (!clientName || clientName === "Гость") { CF.mode="order"; CF.step="name";
      return "Оформляю заявку. Напишите, пожалуйста, <b>фамилию, имя и отчество</b> получателя услуг."; }
    if (!clientPhone) { CF.mode="order"; CF.step="phone";
      return "Остался телефон для связи — напишите номер, например +7 (999) 000-00-00."; }
    return orderSummary();
  }

  function orderSummary(){
    var total = cart.reduce(function(a,i){ return a + i.price*i.qty; }, 0);
    var lines = cart.map(function(i){
      return '<div class="cf-row"><span>' + esc(i.name) + (i.qty>1 ? " ×"+i.qty : "") + "</span><b>" + money(i.price*i.qty) + "</b></div>";
    }).join("");
    CF.mode = "order"; CF.step = "confirm";
    return "Проверьте заявку:" +
      '<div class="cf-card">' + lines +
      '<div class="cf-row cf-total"><span>Итого</span><b>' + money(total) + "</b></div>" +
      '<div class="cf-row"><span>Получатель</span><b>' + esc(clientName) + "</b></div>" +
      '<div class="cf-row"><span>Телефон</span><b>' + esc(clientPhone) + "</b></div>" +
      '<div class="cf-row"><span>Филиал</span><b>' + esc(currentCityName) + "</b></div></div>" +
      row([
        btn("Отправить заявку", function(){ reset(); sendOrder(); return ""; }, { echo:"Отправить заявку" }),
        btn("Изменить состав", function(){ reset(); openCart(); return ""; }, { cl:"outline" })
      ]);
  }

  /* ═══════════ 3. Заказ такси диалогом ═══════════ */

  var MONTHS = ["января","февраля","марта","апреля","мая","июня","июля","августа","сентября","октября","ноября","декабря"];

  function parseDate(text){
    var t = norm(text), now = new Date();
    function iso(d){ return d.getFullYear() + "-" + String(d.getMonth()+1).padStart(2,"0") + "-" + String(d.getDate()).padStart(2,"0"); }
    if (t.indexOf("послезавтра") >= 0) { var d2 = new Date(now); d2.setDate(d2.getDate()+2); return iso(d2); }
    if (t.indexOf("завтра") >= 0) { var d1 = new Date(now); d1.setDate(d1.getDate()+1); return iso(d1); }
    if (t.indexOf("сегодня") >= 0) return iso(now);
    var m = t.match(/(\d{1,2})[.\-\/\s](\d{1,2})(?:[.\-\/\s](\d{2,4}))?/);
    if (m) {
      var y = m[3] ? (m[3].length === 2 ? 2000 + parseInt(m[3]) : parseInt(m[3])) : now.getFullYear();
      var d = new Date(y, parseInt(m[2]) - 1, parseInt(m[1]));
      if (!m[3] && d < now) d.setFullYear(y + 1);
      return isNaN(d) ? null : iso(d);
    }
    var m2 = t.match(/(\d{1,2})\s+([а-я]+)/);
    if (m2) {
      var mi = MONTHS.findIndex(function(name){ return name.indexOf(m2[2].slice(0,4)) === 0; });
      if (mi >= 0) {
        var dd = new Date(now.getFullYear(), mi, parseInt(m2[1]));
        if (dd < now) dd.setFullYear(now.getFullYear() + 1);
        return iso(dd);
      }
    }
    return null;
  }

  function parseTime(text){
    var t = norm(text);
    var m = t.match(/(\d{1,2})[:.\s-](\d{2})/);
    if (m) {
      var h = parseInt(m[1]), mi = parseInt(m[2]);
      if (h < 24 && mi < 60) return String(h).padStart(2,"0") + ":" + String(mi).padStart(2,"0");
    }
    var m2 = t.match(/(?:^|\D)(\d{1,2})\s*(?:час|ч|утра|вечера|дня)?\s*$/);
    if (m2) { var h2 = parseInt(m2[1]); if (h2 < 24) return String(h2).padStart(2,"0") + ":00"; }
    return null;
  }

  function fmtDate(iso){
    var p = iso.split("-");
    return p[2] + " " + MONTHS[parseInt(p[1]) - 1];
  }
  function fmtShort(iso){ var p = iso.split("-"); return p[2] + "." + p[1]; }

  /* Ближайшая дата поездки и приёмное окно — из общих правил такси. */
  function earliestRide(){ return taxiEarliestRideDate(); }
  function rulesLine(){
    return "Заявку принимают <b>накануне поездки с " + TAXI_RULES.orderFrom + " до " + TAXI_RULES.orderTo +
           "</b>, машина работает <b>с " + TAXI_RULES.rideFrom + " до " + TAXI_RULES.rideTo + "</b>.";
  }

  function startTaxi(){
    var tar = (typeof getTaxiTariffs === "function") ? getTaxiTariffs() : { items: [] };
    if (!tar.items.length) {
      return "В филиале «" + esc(currentCityName) + "» перевозка не оказывается. Уточните возможность поездки по телефону центра." +
        row([ btn("Контакты центра", function(){ showContacts(); return ""; }, { cl:"outline" }) ]);
    }
    CF.mode = "taxi"; CF.step = "from"; CF.data = {};
    var first = earliestRide();
    var closed = !taxiOrderWindowOpen();
    return '<div class="cf-warn">' + rulesLine() +
      (closed ? " Сейчас приём заявок закрыт, поэтому ближайшая возможная поездка — <b>" + fmtDate(first) + "</b>."
              : " Ближайшая возможная поездка — <b>" + fmtDate(first) + "</b>.") + "</div>" +
      "Оформим заказ по шагам. <b>Откуда вас забрать?</b> Напишите адрес — улицу и дом.";
  }

  function taxiTariffStep(){
    CF.step = "tariff";
    var tar = getTaxiTariffs();
    var buttons = tar.items.map(function(t){
      var price = (hasMoroshka && t.moroshka != null) ? t.moroshka : t.base;
      return btn(esc(t.label) + " · " + money(price), function(){
        CF.data.tariff = t; CF.data.isFree = false; CF.data.price = price;
        return taxiConfirmStep();
      }, { cl:"outline", echo:t.label });
    });
    var elig = (typeof checkFreeTaxiEligibility === "function") ? checkFreeTaxiEligibility() : { eligible:false };
    var quota = (typeof getFreeTaxiQuota === "function") ? getFreeTaxiQuota() : { remaining:0, limit:0 };
    if (elig.eligible && quota.remaining > 0) {
      buttons.unshift(btn("Льготная поездка · бесплатно", function(){
        CF.data.tariff = { idx:null, label:"Социальное такси — льготная поездка", duration:"30", base:0, moroshka:null };
        CF.data.isFree = true; CF.data.price = 0;
        return taxiConfirmStep();
      }, { echo:"Льготная поездка" }));
    }
    return "Остался тариф. " + (elig.eligible && quota.remaining > 0
        ? "У вас есть право на льготные поездки, осталось " + quota.remaining + " из " + quota.limit + " в этом году."
        : "Выберите подходящий:") + row(buttons);
  }

  function taxiConfirmStep(){
    CF.step = "confirm";
    var d = CF.data;
    return "Проверьте заказ:" +
      '<div class="cf-card">' +
      '<div class="cf-row"><span>Откуда</span><b>' + esc(d.from) + "</b></div>" +
      '<div class="cf-row"><span>Куда</span><b>' + esc(d.to) + "</b></div>" +
      '<div class="cf-row"><span>Когда</span><b>' + fmtDate(d.date) + ", " + d.time + "</b></div>" +
      '<div class="cf-row"><span>Пассажиров</span><b>' + (d.pax||1) + "</b></div>" +
      '<div class="cf-row"><span>Тариф</span><b>' + esc(d.tariff.label) + "</b></div>" +
      '<div class="cf-row cf-total"><span>Стоимость</span><b>' + (d.isFree ? "Бесплатно" : money(d.price)) + "</b></div>" +
      '<div class="cf-row"><span>Получатель</span><b>' + esc(clientName) + "</b></div>" +
      '<div class="cf-row"><span>Телефон</span><b>' + esc(clientPhone) + "</b></div></div>" +
      row([
        btn("Отправить заказ", function(){ return taxiSend(); }, { echo:"Отправить заказ" }),
        btn("Отменить", function(){ reset(); return "Отменил. Если понадобится — напишите «такси», начнём заново."; }, { cl:"outline" })
      ]);
  }

  function taxiSend(){
    var d = CF.data;
    var rule = taxiCheckRide(d.date, d.time);
    if (!rule.ok) { CF.step = "date"; return '<div class="cf-warn">' + esc(rule.message) + "</div>Напишите другую дату."; }
    var existing = JSON.parse(localStorage.getItem("taxiHistory") || "[]");
    var clash = existing.find(function(o){ return o.date === d.date && o.time === d.time && o.status !== "cancelled"; });
    if (clash) { CF.step = "time";
      return "На это время у вас уже есть заказ " + esc(clash.num) + ". Напишите другое время поездки."; }
    var res = taxiSubmitOrder({
      tariff:d.tariff, isFree:d.isFree, price:d.price, from:d.from, to:d.to,
      date:d.date, time:d.time, comment:"Заказ оформлен через чат-бота",
      pax:d.pax||1, passengerNames:[clientName].filter(Boolean)
    });
    reset();
    return "Готово! Заказ такси оформлен, талон <b>" + res.ticketNum + "</b>." +
      '<div class="cf-card"><div class="cf-row"><span>Маршрут</span><b>' + esc(d.from) + " → " + esc(d.to) + "</b></div>" +
      '<div class="cf-row"><span>Подача</span><b>' + fmtDate(d.date) + ", " + d.time + "</b></div>" +
      '<div class="cf-row"><span>Стоимость</span><b>' + (d.isFree ? "Бесплатно" : money(d.price)) + "</b></div></div>" +
      "Открылся почтовый клиент — нажмите «Отправить», и заявка уйдёт диспетчеру. Он свяжется с вами для подтверждения." +
      row([ btn("Мои заказы", function(){ openOrdersPanel(); return ""; }, { cl:"outline" }) ]);
  }

  /* ═══════════ Обработка шагов диалога ═══════════ */

  function handleStep(q){
    var t = q.trim();
    if (/^(отмена|стоп|хватит|отменить|назад в меню)$/i.test(t)) { reset(); return "Отменил. Чем ещё помочь?"; }

    if (CF.mode === "order") {
      if (CF.step === "pick") {
        var list = findServices(t, 6);
        if (!list.length) return "Не нашёл такую услугу в прейскуранте филиала «" + esc(currentCityName) +
          "». Попробуйте другое название или откройте полный список." +
          row([ btn("Открыть прейскурант", function(){ reset(); showServices(); return ""; }, { cl:"outline" }) ]);
        reset();
        if (list.length === 1 && list.full) return answerService(list[0]);
        return answerChoice(list, list.full ? null : "Точного совпадения не нашёл. Возможно, подойдёт что-то из этого:");
      }
      if (CF.step === "name") {
        if (t.split(/\s+/).length < 2) return "Напишите фамилию, имя и отчество полностью — так специалист найдёт вас в базе.";
        clientName = t; localStorage.setItem("clientName", clientName);
        if (!clientPhone) { CF.step = "phone"; return "Записал. Теперь номер телефона для связи."; }
        return orderSummary();
      }
      if (CF.step === "phone") {
        var digits = t.replace(/\D/g, "");
        if (digits.length < 10) return "Похоже, в номере не хватает цифр. Напишите телефон полностью, например +7 (999) 000-00-00.";
        clientPhone = t; localStorage.setItem("clientPhone", clientPhone);
        return orderSummary();
      }
      if (CF.step === "confirm") return orderSummary();
    }

    if (CF.mode === "taxi") {
      if (CF.step === "from") {
        if (t.length < 4) return "Напишите адрес подробнее — улицу и номер дома.";
        CF.data.from = t; CF.step = "to";
        return "Записал: <b>" + esc(t) + "</b>.<br><b>Куда едем?</b> Напишите адрес назначения.";
      }
      if (CF.step === "to") {
        if (t.length < 4) return "Напишите адрес назначения подробнее — улицу и номер дома.";
        CF.data.to = t; CF.step = "date";
        var first = earliestRide();
        return "Маршрут: <b>" + esc(CF.data.from) + " → " + esc(t) + "</b>.<br>" +
          "<b>На какую дату?</b> Можно словами — «завтра», «послезавтра» — или числом, например " + fmtShort(first) +
          ". Ближайшая доступная дата — <b>" + fmtDate(first) + "</b>.";
      }
      if (CF.step === "date") {
        var d = parseDate(t);
        if (!d) return "Не разобрал дату. Напишите «завтра», «послезавтра» или в формате 15.10.";
        var chk = taxiCheckRide(d, TAXI_RULES.rideFrom);
        if (!chk.ok && chk.code === "early") {
          return '<div class="cf-warn">' + rulesLine() + "</div>На эту дату оформить не получится. Ближайшая доступная — <b>" +
            fmtDate(chk.min) + "</b>. Напишите другую дату.";
        }
        CF.data.date = d; CF.step = "time";
        return "Дата: <b>" + fmtDate(d) + "</b>.<br><b>Во сколько подать машину?</b> Машина работает с " +
          TAXI_RULES.rideFrom + " до " + TAXI_RULES.rideTo + " — например, 09:30.";
      }
      if (CF.step === "time") {
        var tm = parseTime(t);
        if (!tm) return "Не разобрал время. Напишите в формате 09:30 или просто «10».";
        var check = taxiCheckRide(CF.data.date, tm);
        if (!check.ok) {
          if (check.code === "hours")
            return '<div class="cf-warn">Машина работает с ' + TAXI_RULES.rideFrom + " до " + TAXI_RULES.rideTo +
              ", позже подачи нет.</div>Напишите время в этом промежутке — например, 09:30 или 17:00.";
          CF.step = "date";
          return '<div class="cf-warn">' + esc(check.message) + "</div>Напишите другую дату.";
        }
        CF.data.time = tm; CF.step = "pax";
        return "Подача: <b>" + fmtDate(CF.data.date) + ", " + tm + "</b>.<br><b>Сколько человек поедет?</b>" +
          row([
            btn("Один", function(){ CF.data.pax = 1; return taxiTariffStep(); }, { cl:"outline", echo:"Один" }),
            btn("Двое", function(){ CF.data.pax = 2; return taxiTariffStep(); }, { cl:"outline", echo:"Двое" })
          ]);
      }
      if (CF.step === "pax") {
        var n = parseInt(t.replace(/\D/g, "")) || 1;
        CF.data.pax = Math.min(2, Math.max(1, n));
        return taxiTariffStep();
      }
      if (CF.step === "tariff") return taxiTariffStep();
      if (CF.step === "confirm") return taxiConfirmStep();
    }
    return null;
  }

  /* ═══════════ Разбор нового сообщения ═══════════ */

  function route(q){
    var t = norm(q);

    var stepAnswer = CF.mode ? handleStep(q) : null;
    if (stepAnswer) return stepAnswer;

    /* Такси */
    if (/такси|машин[ау]|довез|подвез|перевозк/.test(t) && !/сколько стоит|цена|тариф[ыи]?$/.test(t)) return startTaxi();

    /* Оформление заявки */
    if (/оформ|заказ|закаж|хочу|нужн[аоы]|добав|запиши|запис/.test(t)) {
      var found = findServices(q, 6);
      if (found.length === 1 && found.full) return answerService(found[0]);
      if (found.length) return answerChoice(found, found.full ? null : "Точного совпадения не нашёл. Возможно, подойдёт что-то из этого:");
      if (/заявк|оформ|заказ/.test(t) && cart.length) return startOrder();
      if (/заявк|оформ|заказ/.test(t)) {
        CF.mode = "order"; CF.step = "pick";
        return "Готов оформить заявку. Напишите, какая услуга нужна — например «уборка квартиры» или «массаж».";
      }
    }

    /* Состав заявки */
    if (/что в заявке|моя заявка|корзин/.test(t)) {
      if (!cart.length) return "Заявка пока пустая. Напишите, какая услуга нужна — найду и добавлю.";
      return orderSummary();
    }

    /* Цена / подробности услуги */
    if (/сколько стоит|цена|стоимость|сколько по времени|длительност|сколько минут|входит ли|есть ли/.test(t)) {
      var byCat = findCategory(q);
      var svc = findServices(q, 6);
      if (svc.length === 1 && svc.full) return answerService(svc[0]);
      if (svc.length) return answerChoice(svc, svc.full ? "Вот что нашлось по вашему запросу — какая услуга нужна?" : "Точного совпадения не нашёл. Возможно, подойдёт что-то из этого:");
      if (byCat) return answerCategory(byCat);
    }

    /* Раздел целиком */
    if (/что входит|какие услуги|что есть в разделе|список|перечень/.test(t)) {
      var cat = findCategory(q);
      if (cat) return answerCategory(cat);
    }

    /* Прямое совпадение с услугой без ключевых слов */
    var direct = findServices(q, 4);
    if (direct.length === 1 && direct.full) return answerService(direct[0]);
    if (direct.length > 1 && direct.full) {
      var cat2 = findCategory(q);
      if (cat2) return answerCategory(cat2);
      return answerChoice(direct, "Вот что нашлось по запросу:");
    }

    return null; /* дальше отвечает обычный smartAsk */
  }

  /* ═══════════ Подключение к чату ═══════════ */

  var baseAskFlow = window.askFlow;
  window.askFlow = function(query){
    addMsg(query, false);
    var html = null;
    try { html = route(query); }
    catch (e) { console.error("chatflow:", e); reset(); }
    if (html) { say(html); return; }
    showTyping(function(){
      var res = smartAsk(query);
      var out = res.answer;
      if (res.actions && res.actions.length) {
        out += '<div class="asst-actions">' + res.actions.map(function(a){
          return '<button type="button" class="act-btn ' + (a.cl||"teal") + '" onclick="asstGo(\'' + a.fn + '\'' +
                 (a.arg !== undefined ? "," + a.arg : "") + (a.arg2 !== undefined ? "," + a.arg2 : "") + ')">' + a.label + "</button>";
        }).join("") + "</div>";
      }
      addMsg(out, true);
    });
  };

  /* Быстрые подсказки под приветствием бота. */
  window.cfHints = function(){
    return row([
      btn("Заказать такси", function(){ return startTaxi(); }, { echo:"Заказать такси" }),
      btn("Оформить заявку", function(){ return startOrder(); }, { cl:"outline", echo:"Оформить заявку" }),
      btn("Что есть в прейскуранте", function(){ reset(); showServices(); return ""; }, { cl:"outline" })
    ]);
  };
})();
